class DataIntegrityError(OSError):
    """Raised when saved records cannot be safely read or recovered."""


def _fsync_directory(directory):
    """Best-effort directory sync after atomic replacement (supported on many POSIX systems)."""
    if os.name == "nt":
        return
    descriptor = None
    try:
        descriptor = os.open(directory, os.O_RDONLY)
        os.fsync(descriptor)
    except (OSError, AttributeError):
        pass
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError:
                pass


def _atomic_write_bytes(path, content):
    """Write to a same-directory temporary file, flush it, then atomically replace the target."""
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    descriptor, temp_path = tempfile.mkstemp(prefix="." + os.path.basename(path) + ".", suffix=".tmp", dir=directory)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, path)
        _fsync_directory(directory)
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass


def _json_bytes(data):
    return (json.dumps(data, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode("utf-8")


def _valid_jobs_payload(data):
    if not isinstance(data, list):
        return False
    valid_types = {"T-shirt", "Shorts", "Jersey"}
    for item in data:
        if not isinstance(item, dict):
            return False
        try:
            if "quantity" in item and "type" in item:
                quantity = int(item.get("quantity", 0))
                if quantity < 1 or str(item.get("type")) not in valid_types:
                    return False
            elif "completed" in item:  # Legacy format retained by the migration code below.
                if int(item.get("completed", 0)) < 1:
                    return False
            else:
                return False
        except (TypeError, ValueError, OverflowError):
            return False
    return True


def _valid_debt_payload(data):
    if not isinstance(data, dict):
        return False
    try:
        balance = int(data.get("balance_centavos", 0))
    except (TypeError, ValueError, OverflowError):
        return False
    if balance < 0:
        return False
    transactions = data.get("transactions", [])
    if not isinstance(transactions, list) or any(not isinstance(item, dict) for item in transactions):
        return False
    for transaction in transactions:
        if "amount_centavos" in transaction:
            try:
                if int(transaction.get("amount_centavos", 0)) < 0:
                    return False
            except (TypeError, ValueError, OverflowError):
                return False
    return True


def _read_valid_json(path, validator):
    with open(path, "rb") as handle:
        raw = handle.read()
    parsed = json.loads(raw.decode("utf-8"))
    if not validator(parsed):
        raise ValueError("saved data does not match the expected format")
    return parsed, raw


def _write_snapshot(path, raw):
    """Persist one versioned copy of previously valid bytes in the recovery folder."""
    os.makedirs(BACKUP_DIR, exist_ok=True)
    stamp = datetime.now(MANILA_TZ).strftime("%Y%m%d_%H%M%S_%f")
    snapshot = os.path.join(BACKUP_DIR, f"{os.path.basename(path)}.{stamp}.json")
    _atomic_write_bytes(snapshot, raw)
    _prune_snapshots(path)


def _ensure_current_backup_mirror(path, current_raw, validator):
    """On first use, establish a backup; if primary is newer, archive prior mirror before refreshing it."""
    mirror = path + ".bak"
    if not os.path.exists(mirror):
        try:
            _atomic_write_bytes(mirror, current_raw)
        except OSError as exc:
            print(f"[DATA SAFETY] Warning: couldn't create the initial backup for {os.path.basename(path)}: {exc}")
        return

    try:
        _mirror_data, mirror_raw = _read_valid_json(mirror, validator)
    except (OSError, json.JSONDecodeError, UnicodeDecodeError, ValueError, TypeError):
        # Keep a damaged mirror for investigation, then regenerate it from the validated primary.
        try:
            with open(mirror, "rb") as handle:
                damaged_mirror = handle.read()
            stamp = datetime.now(MANILA_TZ).strftime("%Y%m%d_%H%M%S_%f")
            _atomic_write_bytes(mirror + ".corrupt." + stamp, damaged_mirror)
            _atomic_write_bytes(mirror, current_raw)
        except OSError as exc:
            print(f"[DATA SAFETY] Warning: couldn't refresh the backup mirror for {os.path.basename(path)}: {exc}")
        return

    if mirror_raw != current_raw:
        # A crash may have occurred after the primary was saved but before its mirror was updated.
        # Retain the old valid mirror as a snapshot before making the current valid primary the latest mirror.
        try:
            _write_snapshot(path, mirror_raw)
            _atomic_write_bytes(mirror, current_raw)
        except OSError as exc:
            print(f"[DATA SAFETY] Warning: couldn't refresh the backup mirror for {os.path.basename(path)}: {exc}")


def _backup_candidates(path):
    """Prefer the latest known-good mirror, then timestamped snapshots newest-first."""
    candidates = []
    mirror = path + ".bak"
    if os.path.isfile(mirror):
        candidates.append(mirror)
    pattern = os.path.join(BACKUP_DIR, os.path.basename(path) + ".*.json")
    snapshots = [candidate for candidate in glob.glob(pattern) if os.path.isfile(candidate)]
    snapshots.sort(key=lambda candidate: os.path.getmtime(candidate), reverse=True)
    candidates.extend(candidate for candidate in snapshots if candidate not in candidates)
    return candidates


def _prune_snapshots(path):
    pattern = os.path.join(BACKUP_DIR, os.path.basename(path) + ".*.json")
    snapshots = [candidate for candidate in glob.glob(pattern) if os.path.isfile(candidate)]
    snapshots.sort(key=lambda candidate: os.path.getmtime(candidate), reverse=True)
    for obsolete in snapshots[MAX_DATA_BACKUPS:]:
        try:
            os.remove(obsolete)
        except OSError:
            pass


def _snapshot_previous_valid_file(path, validator):
    """Archive the current good version before replacing it; never back up invalid bytes as good data."""
    if not os.path.exists(path):
        return
    try:
        _old_data, old_raw = _read_valid_json(path, validator)
    except (json.JSONDecodeError, UnicodeDecodeError, ValueError, TypeError) as exc:
        raise DataIntegrityError(
            f"The existing data file '{os.path.basename(path)}' failed validation. It was not overwritten."
        ) from exc
    except OSError as exc:
        raise DataIntegrityError(
            f"The existing data file '{os.path.basename(path)}' could not be read, so it was not overwritten."
        ) from exc

    _write_snapshot(path, old_raw)


def _load_json_with_recovery(path, validator, default, description):
    """Load valid primary data or restore the latest valid backup without discarding corrupt files."""
    primary_exists = os.path.exists(path)
    primary_error = None
    if primary_exists:
        try:
            data, raw = _read_valid_json(path, validator)
            _ensure_current_backup_mirror(path, raw, validator)
            return data
        except (json.JSONDecodeError, UnicodeDecodeError, ValueError, TypeError) as exc:
            primary_error = exc
        except OSError as exc:
            raise DataIntegrityError(
                f"The {description} data file could not be read. No saved data was changed."
            ) from exc

    candidates = _backup_candidates(path)
    for candidate in candidates:
        try:
            recovered, backup_raw = _read_valid_json(candidate, validator)
        except (OSError, json.JSONDecodeError, UnicodeDecodeError, ValueError, TypeError):
            continue

        if primary_exists:
            try:
                with open(path, "rb") as handle:
                    damaged_raw = handle.read()
                stamp = datetime.now(MANILA_TZ).strftime("%Y%m%d_%H%M%S_%f")
                _atomic_write_bytes(path + ".corrupt." + stamp, damaged_raw)
            except OSError as exc:
                raise DataIntegrityError(
                    f"A backup exists for the {description} data, but the damaged file could not be preserved safely. No data was overwritten."
                ) from exc

        try:
            _atomic_write_bytes(path, backup_raw)
            # Refresh the latest-known-good mirror; if that copy fails, the restored primary still remains intact.
            try:
                _atomic_write_bytes(path + ".bak", backup_raw)
            except OSError as exc:
                print(f"[DATA SAFETY] Recovered {description}, but could not refresh its backup mirror: {exc}")
        except OSError as exc:
            raise DataIntegrityError(
                f"A valid backup for {description} was found but could not be restored. No new records will be written."
            ) from exc
        print(f"[DATA SAFETY] Recovered {description} from a valid backup: {os.path.basename(candidate)}")
        return recovered

    if primary_exists or candidates:
        reason = "the main file is missing or invalid, and no valid backup was found" if not primary_exists else "the main file is invalid, and no valid backup was found"
        raise DataIntegrityError(
            f"The {description} data could not be verified ({reason}). The original file was preserved and will not be overwritten."
        ) from primary_error
    return default


def _save_json_with_backups(path, data, validator, description):
    """Durably save JSON and keep a latest-good mirror plus up to 50 previous snapshots."""
    if not validator(data):
        raise ValueError(f"Refusing to save invalid {description} data.")
    with PRODUCTION_LOCK:
        _snapshot_previous_valid_file(path, validator)
        payload = _json_bytes(data)
        _atomic_write_bytes(path, payload)
        # Keep an exact mirror of the latest successful save. Failure here is non-fatal because
        # the primary file has already been atomically saved; previous snapshots remain available.
        try:
            _atomic_write_bytes(path + ".bak", payload)
        except OSError as exc:
            print(f"[DATA SAFETY] Warning: {description} was saved, but the latest backup mirror could not be refreshed: {exc}")
        _prune_snapshots(path)

