def load_jobs():
    """Load production entries, recovering from validated backups instead of silently returning empty data."""
    with PRODUCTION_LOCK:
        data = _load_json_with_recovery(PRODUCTION_FILE, _valid_jobs_payload, [], "production")

        entries = []
        valid_types = {"T-shirt", "Shorts", "Jersey"}
        for item in data:
            try:
                if "quantity" in item and "type" in item:
                    quantity = int(item.get("quantity", 0))
                    item_type = str(item.get("type", "Jersey"))
                    entries.append({
                        "id": str(item.get("id") or secrets.token_hex(8)),
                        "type": item_type,
                        "quantity": quantity,
                        "created": str(item.get("created", "")),
                    })
                elif "completed" in item:
                    # Older saved work orders are migrated to completed-piece entries, not discarded.
                    quantity = int(item.get("completed", 0))
                    old_design = str(item.get("design", "")).lower()
                    if "short" in old_design:
                        item_type = "Shorts"
                    elif "t-shirt" in old_design or "t shirt" in old_design or "shirt" in old_design:
                        item_type = "T-shirt"
                    else:
                        item_type = "Jersey"
                    entries.append({
                        "id": "legacy-" + str(item.get("id") or secrets.token_hex(8)),
                        "type": item_type,
                        "quantity": quantity,
                        "created": str(item.get("created", "")),
                    })
            except (ValueError, TypeError, OverflowError):
                # The store validator checks every entry before this migration loop.
                continue
        return entries


