def amount_to_centavos(value):
    """Return an integer centavo amount, or None when input is not valid currency."""
    try:
        amount = Decimal(str(value).strip())
        if not amount.is_finite() or amount <= 0:
            return None
        rounded = amount.quantize(Decimal("0.01"))
        if amount != rounded:
            return None
        centavos = int(rounded * 100)
        return centavos if 0 < centavos <= 10_000_000_000 else None
    except (InvalidOperation, ValueError, TypeError):
        return None


def format_money_centavos(centavos):
    """Format integer centavos as Philippine pesos without unnecessary decimal zeros."""
    amount = int(centavos)
    sign = "-" if amount < 0 else ""
    amount = abs(amount)
    pesos, cents = divmod(amount, 100)
    formatted = f"{pesos:,}"
    if cents:
        formatted += f".{cents:02d}"
    return f"{sign}₱{formatted}"


def format_number(number):
    return f"{int(number):,}"


def current_manila_datetime():
    """Return the current date and time in Philippines time (UTC+08:00)."""
    return datetime.now(MANILA_TZ)


def format_date_english(value):
    """Format a date with English month names for the visible interface."""
    months = (
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December",
    )
    return f"{months[value.month - 1]} {value.day}, {value.year}"


def format_created(value):
    """Format ISO timestamps nicely while being honest about older date-only records."""
    value = str(value or "").strip()
    if not value:
        return "Date not recorded"
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return value
    has_time = "T" in value or (" " in value and len(value) > 10)
    if not has_time:
        return format_date_english(parsed) + " · time not recorded"
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=MANILA_TZ)
    else:
        parsed = parsed.astimezone(MANILA_TZ)
    return format_date_english(parsed) + " · " + parsed.strftime("%H:%M:%S") + " (Philippine Time)"


def format_earning_label(value):
    """Label entry earnings by their actual saved date in Manila time."""
    value = str(value or "").strip()
    if not value:
        return "Earnings date not recorded"
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return "Earnings for recorded date"
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=MANILA_TZ)
    else:
        parsed = parsed.astimezone(MANILA_TZ)
    if parsed.date() == current_manila_datetime().date():
        return "Earned Today"
    return "Earned on " + format_date_english(parsed)


