    debt_transactions = michael_debt.get("transactions", [])
    debt_history_rows = []
    if isinstance(debt_transactions, list):
        # Transactions are appended in time order; newest activity appears first.
        for display_index, transaction in enumerate(reversed(debt_transactions[-500:])):
            if not isinstance(transaction, dict):
                continue
            # Stable fallback IDs let older saved transactions be deleted without a migration.
            transaction_id = str(transaction.get("id") or f"legacy-{len(debt_transactions) - 1 - display_index}")
            try:
                amount_centavos = int(transaction.get("amount_centavos", 0))
            except (TypeError, ValueError):
                continue
            if amount_centavos <= 0:
                continue
            transaction_type = str(transaction.get("type", ""))
