def _password_digest(password, salt):
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, AUTH_PBKDF2_ITERATIONS)


def _store_password(password):
    """Persist a salted PBKDF2 hash only; never write the password itself to disk."""
    global _PASSWORD_SALT, _PASSWORD_HASH
    _PASSWORD_SALT = secrets.token_bytes(16)
    _PASSWORD_HASH = _password_digest(password, _PASSWORD_SALT)
    config = {
        "algorithm": "pbkdf2_sha256",
        "iterations": AUTH_PBKDF2_ITERATIONS,
        "salt": _PASSWORD_SALT.hex(),
        "password_hash": _PASSWORD_HASH.hex(),
    }
    _atomic_write_bytes(AUTH_FILE, _json_bytes(config))
    try:
        os.chmod(AUTH_FILE, 0o600)
    except OSError:
        pass  # Windows ACLs, not POSIX mode bits, control Windows file access.


def initialize_authentication():
    """Load saved credentials without prompting for a password in the terminal."""
    global _PASSWORD_SALT, _PASSWORD_HASH
    env_password = os.environ.get("LOGIN_PASSWORD")
    if env_password is not None:
        if not env_password.strip():
            print("Security setup failed: LOGIN_PASSWORD cannot be empty.")
            return False
        _PASSWORD_SALT = secrets.token_bytes(16)
        _PASSWORD_HASH = _password_digest(env_password, _PASSWORD_SALT)
        return True

    if os.path.exists(AUTH_FILE):
        try:
            with open(AUTH_FILE, "r", encoding="utf-8") as handle:
                config = json.load(handle)
            if config.get("algorithm") != "pbkdf2_sha256":
                raise ValueError("unsupported password hash algorithm")
            _PASSWORD_SALT = bytes.fromhex(config["salt"])
            _PASSWORD_HASH = bytes.fromhex(config["password_hash"])
            if len(_PASSWORD_SALT) < 16 or len(_PASSWORD_HASH) != 32:
                raise ValueError("invalid password hash data")
            return True
        except (OSError, ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
            print(f"Security setup failed: {AUTH_FILE} could not be read safely ({exc}).")
            print("Fix or rename that file and restart. The site has been kept locked.")
            return False

    # Keep the original project's local sign-in working on a fresh install without
    # blocking startup for terminal input. A custom LOGIN_PASSWORD environment
    # variable can override this fallback; existing jersey_auth.json always persists.
    try:
        _store_password(env_password if env_password is not None else LEGACY_FIRST_RUN_PASSWORD)
        return True
    except OSError as exc:
        print(f"Security setup failed: could not save local authentication ({exc}).")
        return False


def verify_login_password(submitted):
    if _PASSWORD_SALT is None or _PASSWORD_HASH is None:
        return False
    try:
        candidate = _password_digest(submitted, _PASSWORD_SALT)
        return hmac.compare_digest(candidate, _PASSWORD_HASH)
    except (AttributeError, UnicodeError):
        return False


def create_session_token():
    """Create an unpredictable session ID stored only in server memory."""
    token = secrets.token_urlsafe(32)
    now = time.time()
    with SESSION_LOCK:
        expired = [key for key, value in SESSIONS.items() if value.get("expires", 0) <= now]
        for key in expired:
            SESSIONS.pop(key, None)
        SESSIONS[token] = {
            "expires": now + SESSION_TTL_SECONDS,
            "csrf": secrets.token_urlsafe(32),
        }
    return token


def is_valid_token(token):
    if not token:
        return False
    now = time.time()
    with SESSION_LOCK:
        session = SESSIONS.get(token)
        if not session:
            return False
        if session.get("expires", 0) <= now:
            SESSIONS.pop(token, None)
            return False
        return True


def session_csrf_token(token):
    if not token:
        return ""
    now = time.time()
    with SESSION_LOCK:
        session = SESSIONS.get(token)
        if not session or session.get("expires", 0) <= now:
            SESSIONS.pop(token, None)
            return ""
        return str(session.get("csrf", ""))


def revoke_session_token(token):
    if token:
        with SESSION_LOCK:
            SESSIONS.pop(token, None)


def login_is_locked(client_key):
    now = time.time()
    with LOGIN_ATTEMPTS_LOCK:
        record = LOGIN_ATTEMPTS.get(client_key)
        if not record:
            return False, 0
        locked_until = float(record.get("locked_until", 0))
        if locked_until > now:
            return True, max(1, int(locked_until - now + 0.999))
        if locked_until:
            LOGIN_ATTEMPTS.pop(client_key, None)
        elif now - float(record.get("window_start", now)) > LOGIN_WINDOW_SECONDS:
            LOGIN_ATTEMPTS.pop(client_key, None)
        return False, 0


def record_failed_login(client_key):
    now = time.time()
    with LOGIN_ATTEMPTS_LOCK:
        record = LOGIN_ATTEMPTS.get(client_key)
        if not record or now - float(record.get("window_start", now)) > LOGIN_WINDOW_SECONDS:
            record = {"failures": 0, "window_start": now, "locked_until": 0}
        record["failures"] = int(record.get("failures", 0)) + 1
        if record["failures"] >= LOGIN_MAX_ATTEMPTS:
            record["locked_until"] = now + LOGIN_LOCKOUT_SECONDS
        LOGIN_ATTEMPTS[client_key] = record
        return int(record.get("locked_until", 0)) > now


def clear_login_failures(client_key):
    with LOGIN_ATTEMPTS_LOCK:
        LOGIN_ATTEMPTS.pop(client_key, None)


def _compact_inline_code(source, language):
    """Compact inline CSS/JS sent to browsers; this is not encryption or source protection."""
    out = []
    i = 0
    quote = None
    escaped = False
    pending_space = False
    n = len(source)
    punctuation = set("{}();,:=<>")

    while i < n:
        ch = source[i]

        if quote:
            out.append(ch)
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
            i += 1
            continue

        # Preserve strings exactly so spaces inside text/values are not changed.
        if ch in ("'", '"', '`'):
            if pending_space and out and out[-1] not in punctuation:
                out.append(" ")
            pending_space = False
            quote = ch
            out.append(ch)
            i += 1
            continue

        # Strip CSS/JS comments outside quoted strings.
        if source.startswith("/*", i):
            end = source.find("*/", i + 2)
            i = n if end < 0 else end + 2
            pending_space = True
            continue
        if language == "js" and source.startswith("//", i):
            end = source.find("\n", i + 2)
            i = n if end < 0 else end + 1
            pending_space = True
            continue

        if ch.isspace():
            pending_space = True
            i += 1
            continue

        if pending_space and out:
            previous = out[-1]
            # Keep a separator between token-like characters, but discard
            # formatting spaces beside punctuation where JavaScript/CSS allow it.
            if previous not in punctuation and ch not in punctuation:
                out.append(" ")
        pending_space = False
        out.append(ch)
        i += 1

    return "".join(out).strip()


def compact_frontend_html(markup):
    """Reduce formatting in browser responses. HTML/CSS/JS still remain inspectable."""
    def compact_style(match):
        return match.group(1) + _compact_inline_code(match.group(2), "css") + match.group(3)

    def compact_script(match):
        return match.group(1) + _compact_inline_code(match.group(2), "js") + match.group(3)

    markup = re.sub(r"(<style\b[^>]*>)(.*?)(</style\s*>)", compact_style, markup, flags=re.IGNORECASE | re.DOTALL)
    markup = re.sub(r"(<script\b[^>]*>)(.*?)(</script\s*>)", compact_script, markup, flags=re.IGNORECASE | re.DOTALL)
    # Remove indentation/newlines between tags without removing intentional inline spaces.
    markup = re.sub(r">[ \t]*\r?\n[ \t]*<", "><", markup)
    return markup.strip()

class JerseyHandler(BaseHTTPRequestHandler):
    server_version = "JerseyPrinting"
    sys_version = ""

    def log_message(self, fmt, *args):
        # Never log request bodies or submitted passwords.
        print("[%s] %s" % (self.log_date_time_string(), fmt % args))

    def _headers(self, status=200, content_type="text/html; charset=utf-8"):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header("Permissions-Policy", "autoplay=(self \"https://www.youtube.com\"), camera=(), microphone=(), geolocation=()")
        self.send_header("Cache-Control", "no-store, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.send_header(
            "Content-Security-Policy",
            "default-src 'self' data:; img-src 'self' data:; "
            "style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; "
            "frame-src https://www.youtube-nocookie.com https://www.youtube.com; "
            "form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'; connect-src 'self'",
        )

    def _host_is_allowed(self):
        # The app binds only to loopback. Accept only the local alias and loopback hostnames.
        raw_host = (self.headers.get("Host", "") or "").strip().lower()
        if raw_host.startswith("[") and "]" in raw_host:
            host = raw_host[1:raw_host.index("]")]
        else:
            host = raw_host.split(":", 1)[0]
        allowed = {"127.0.0.1", "localhost", DISPLAY_HOST.lower()}
        return host in allowed

    def _send_html(self, body, status=200, cookie_headers=None):
        # Compacting is only deterrence to casual reading; client code remains inspectable.
        payload = compact_frontend_html(body).encode("utf-8")
        self._headers(status)
        if cookie_headers:
            values = [cookie_headers] if isinstance(cookie_headers, str) else list(cookie_headers)
            for value in values:
                self.send_header("Set-Cookie", value)
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _redirect(self, location, cookie_header=None, status=303):
        self.send_response(status)
        self.send_header("Location", location)
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header("Cache-Control", "no-store, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.send_header("Content-Security-Policy", "default-src 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'")
        if cookie_header:
            values = [cookie_header] if isinstance(cookie_header, str) else list(cookie_header)
            for value in values:
                self.send_header("Set-Cookie", value)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _cookie_value(self, name):
        cookie = SimpleCookie()
        try:
            cookie.load(self.headers.get("Cookie", ""))
            morsel = cookie.get(name)
            return morsel.value if morsel else ""
        except Exception:
            return ""

    def _session_token(self):
        return self._cookie_value("jp_session")

    def _is_logged_in(self):
        return is_valid_token(self._session_token())

    def _show_login(self, error="", status=200):
        csrf = secrets.token_urlsafe(32)
        cookie = f"jp_login_csrf={csrf}; Max-Age=600; Path=/; HttpOnly; SameSite=Strict"
        self._send_html(render_login(error, csrf), status, cookie)

    def _client_key(self):
        # The server binds only to localhost, so this is a per-local-client throttling key.
        return str(self.client_address[0]) if self.client_address else "unknown"

    def do_GET(self):
        if not self._host_is_allowed():
            self._send_html("<h1>400 — Invalid Host</h1>", 400)
            return
        parsed = urlsplit(self.path)
        path = parsed.path
        session_token = self._session_token()
        logged_in = is_valid_token(session_token)
        if path == "/":
            if logged_in:
                self._redirect("/dashboard")
            else:
                self._show_login()
        elif path == "/dashboard":
            if not logged_in:
                revoke_session_token(session_token)
                self._redirect("/")
            else:
                notice = parse_qs(parsed.query).get("notice", [""])[0]
                try:
                    page = render_dashboard(notice, session_csrf_token(session_token))
                except DataIntegrityError:
                    page = render_storage_integrity_error()
                    self._send_html(page, 500)
                    return
                self._send_html(page)
        elif path == "/logout":
            revoke_session_token(session_token)
            self._redirect("/", [
                "jp_session=; Max-Age=0; Path=/; HttpOnly; SameSite=Strict",
                "jp_login_csrf=; Max-Age=0; Path=/; HttpOnly; SameSite=Strict",
            ])
        else:
            self._send_html("<h1>404 — Page Not Found</h1><p><a href='/'>Return to sign in</a></p>", 404)

    def do_POST(self):
        if not self._host_is_allowed():
            self._send_html("<h1>400 — Invalid Host</h1>", 400)
            return
        path = urlsplit(self.path).path
        if path == "/login":
            try:
                length = int(self.headers.get("Content-Length", "0"))
                if length <= 0 or length > 8192:
                    self._show_login("Invalid request. Reload the page and try again.", 400)
                    return
                body = self.rfile.read(length).decode("utf-8", errors="replace")
                fields = parse_qs(body, keep_blank_values=True)
                submitted = fields.get("password", [""])[0]
                submitted_csrf = fields.get("csrf_token", [""])[0]
            except (ValueError, OSError):
                self._show_login("Invalid request. Reload the page and try again.", 400)
                return

            cookie_csrf = self._cookie_value("jp_login_csrf")
            if not cookie_csrf or not submitted_csrf or not hmac.compare_digest(cookie_csrf, submitted_csrf):
                self._show_login("Your sign-in page expired. Reload and try again.", 403)
                return

            client_key = self._client_key()
            locked, seconds_left = login_is_locked(client_key)
            if locked:
                self._show_login(f"Too many failed attempts. Try again in about {max(1, (seconds_left + 59) // 60)} minute(s).", 429)
                return

            if verify_login_password(submitted):
                clear_login_failures(client_key)
                token = create_session_token()
                cookie = f"jp_session={token}; Max-Age={SESSION_TTL_SECONDS}; Path=/; HttpOnly; SameSite=Strict"
                clear_csrf = "jp_login_csrf=; Max-Age=0; Path=/; HttpOnly; SameSite=Strict"
                self._redirect("/dashboard", [cookie, clear_csrf])
            else:
                now_locked = record_failed_login(client_key)
                if now_locked:
                    self._show_login("Too many failed attempts. Try again in 5 minutes.", 429)
                else:
                    self._show_login("Incorrect password. Please try again.", 401)
            return

        valid_routes = {"/production/add", "/production/delete", "/debt/add", "/debt/history/delete", "/debt/history/delete-all"}
        if path not in valid_routes:
            self._send_html("<h1>404 — Page Not Found</h1>", 404)
            return
        session_token = self._session_token()
        if not is_valid_token(session_token):
            revoke_session_token(session_token)
            self._redirect("/")
            return

        expected_csrf = session_csrf_token(session_token)
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 32768:
                self._redirect("/dashboard?notice=invalid")
                return
            body = self.rfile.read(length).decode("utf-8", errors="replace")
            fields = parse_qs(body, keep_blank_values=True)
        except (ValueError, OSError):
            self._redirect("/dashboard?notice=invalid")
            return

        submitted_csrf = fields.get("csrf_token", [""])[0]
        if not expected_csrf or not submitted_csrf or not hmac.compare_digest(expected_csrf, submitted_csrf):
            self._redirect("/dashboard?notice=security")
            return

        try:
            with PRODUCTION_LOCK:
                if path == "/debt/history/delete-all":
                    debt = load_michael_debt()
                    debt["transactions"] = []
                    debt["balance_centavos"] = 0
                    save_michael_debt(debt)
                    self._redirect("/dashboard")
                    return

                if path == "/debt/history/delete":
                    submitted_id = fields.get("transaction_id", [""])[0]
                    debt = load_michael_debt()
                    transactions = debt.get("transactions", [])
                    if not isinstance(transactions, list):
                        transactions = []
                    kept_transactions = []
                    removed_transaction = None
                    for transaction_index, transaction in enumerate(transactions):
                        if not isinstance(transaction, dict):
                            kept_transactions.append(transaction)
                            continue
                        existing_id = str(transaction.get("id") or f"legacy-{transaction_index}")
                        if removed_transaction is None and submitted_id and existing_id == submitted_id:
                            removed_transaction = transaction
                        else:
                            kept_transactions.append(transaction)
                    if removed_transaction is None:
                        self._redirect("/dashboard?notice=debttransactionnotfound")
                        return
                    removed_amount = max(0, int(removed_transaction.get("amount_centavos", 0)))
                    removed_type = str(removed_transaction.get("type", ""))
                    current_balance = max(0, int(debt.get("balance_centavos", 0)))
                    if removed_type == "debt_added":
                        current_balance = max(0, current_balance - removed_amount)
                    elif removed_type == "payment":
                        current_balance += removed_amount
                    debt["transactions"] = kept_transactions
                    debt["balance_centavos"] = current_balance
                    save_michael_debt(debt)
                    self._redirect("/dashboard?notice=debttransactiondeleted")
                    return

                if path == "/debt/add":
                    amount_centavos = amount_to_centavos(fields.get("amount", [""])[0])
                    if amount_centavos is None:
                        self._redirect("/dashboard?notice=debtinvalid")
                        return
                    debt = load_michael_debt()
                    current_balance = max(0, int(debt.get("balance_centavos", 0)))
                    debt["balance_centavos"] = current_balance + amount_centavos
                    transactions = debt.get("transactions", [])
                    if not isinstance(transactions, list):
                        transactions = []
                    transactions.append({
                        "id": secrets.token_hex(8),
                        "type": "debt_added",
                        "amount_centavos": amount_centavos,
                        "created": current_manila_datetime().isoformat(timespec="seconds"),
                    })
                    debt["transactions"] = transactions[-500:]
                    save_michael_debt(debt)
                    self._redirect("/dashboard?notice=debtadded")
                    return

                entries = load_jobs()
                if path == "/production/add":
                    item_type = fields.get("item_type", [""])[0]
                    try:
                        quantity = int(fields.get("quantity", [""])[0])
                    except (ValueError, TypeError):
                        quantity = 0
                    if item_type not in {"T-shirt", "Shorts", "Jersey"} or not 1 <= quantity <= 10000:
                        self._redirect("/dashboard?notice=invalid")
                        return
                    entry = {
                        "id": secrets.token_hex(8),
                        "type": item_type,
                        "quantity": quantity,
                        "created": current_manila_datetime().isoformat(timespec="seconds"),
                    }
                    entries.insert(0, entry)
                    save_jobs(entries)
                    self._redirect("/dashboard?notice=added")
                    return

                entry_id = fields.get("id", [""])[0]
                updated_entries = [entry for entry in entries if str(entry.get("id", "")) != entry_id]
                if len(updated_entries) == len(entries):
                    self._redirect("/dashboard?notice=notfound")
                    return
                save_jobs(updated_entries)
                self._redirect("/dashboard?notice=deleted")
                return
        except (ValueError, OSError, TypeError):
            self._redirect("/dashboard?notice=error")


def main():
    if not initialize_authentication():
        input("Press Enter to exit...")
        return
    address = f"http://{DISPLAY_HOST}:{PORT}"
    try:
        server = ThreadingHTTPServer((HOST, PORT), JerseyHandler)
    except OSError as exc:
        print(f"Could not start the website: {exc}")
        print(f"Port {PORT} may already be in use. Close the other running website first.")
        input("Press Enter to exit...")
        return
    print("\nJersey Printing secure local dashboard is ready.")
    print(f"Open this address: {address}")
    print("Private mode: listening on this computer only (127.0.0.1).")
    print("Password checks, login throttling, server-side sessions, and CSRF protection are enabled.")
    print("Data is saved locally. Press Ctrl+C to stop the website.\n")
    threading.Timer(1.0, lambda: webbrowser.open_new_tab(address)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nWebsite stopped.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
